contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _am) public {
        // Fresh c: MinSum is 0, balances[msg.sender] (this contract) is 0,
        // so Collect(_am) only passes the guard for _am == 0.
        require(_am == 0);
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;

        // This contract's receive() reverts, so the payout call inside
        // Collect fails and Collect must revert as a whole.
        bool reverted;
        c.Collect(_am); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(reverted && address(c).balance == balBefore);
    }

    receive() external payable {
        revert();
    }
}

